const initialQuestions=[{id:1,name:'Bác Minh',initials:'M',age:68,category:'Điện thoại',title:'Làm sao để gọi video cho cháu trên Zalo?',body:'Cháu nội tôi mới đi học xa. Tôi muốn gọi để nhìn thấy cháu nhưng chưa biết bấm vào đâu. Các cháu chỉ giúp tôi từng bước với nhé.',time:'15 phút trước',answers:[{id:'a1',name:'Minh Anh',initials:'MA',body:'Bác làm theo 3 bước này nhé:\n1. Mở Zalo, chọn cuộc trò chuyện với cháu.\n2. Bấm biểu tượng máy quay ở góc trên bên phải.\n3. Chờ cháu nghe máy. Nếu chưa thấy hình, bác cho phép Zalo dùng camera nhé.',likes:12,reviewed:true}]},{id:2,name:'Cô Hương',initials:'H',age:64,category:'An toàn',title:'Có người gọi xin mã OTP, cô có nên đọc không?',body:'Một người tự xưng là nhân viên ngân hàng gọi xin mã OTP để cập nhật tài khoản. Cô chưa đưa mã. Cô nên làm gì tiếp theo?',time:'35 phút trước',answers:[{id:'a2',name:'Tuấn Anh',initials:'TA',body:'Cô đừng cung cấp mã OTP, mật khẩu hay thông tin tài khoản cho người gọi. Cô hãy kết thúc cuộc gọi và liên hệ ngân hàng qua số trên ứng dụng hoặc mặt sau thẻ để kiểm tra. Cô không bấm đường link người lạ gửi nhé.',likes:21,reviewed:true}]},{id:3,name:'Bác Thành',initials:'T',age:71,category:'Điện thoại',title:'Chữ trên điện thoại bé quá, làm sao phóng to?',body:'Bác đọc tin nhắn hơi khó vì chữ nhỏ. Bác dùng điện thoại Android. Có cách nào làm chữ lớn hơn không?',time:'1 giờ trước',answers:[]},{id:4,name:'Cô Mai',initials:'M',age:63,category:'Ứng dụng',title:'Cô muốn gửi ảnh hoa cho bạn thì làm thế nào?',body:'Cô vừa chụp hoa trong vườn, muốn gửi qua Zalo cho mấy người bạn. Các cháu hướng dẫn giúp cô nhé.',time:'2 giờ trước',answers:[]}];
const products=[{id:'tea',name:'Trà hoa cúc nguyên bông',price:89000,category:'Thư giãn',img:'tea',shop:'Vườn Nhà',desc:'Hương hoa dịu nhẹ cho buổi trò chuyện cùng bạn bè. Gói 50g. Thành phần: hoa cúc sấy khô. Đây là đồ uống, không phải sản phẩm điều trị.',sponsored:true},{id:'cup',name:'Cốc gốm có quai dễ cầm',price:125000,category:'Đồ dùng',img:'cup',shop:'Gốm An Nhiên',desc:'Cốc gốm 350ml có quai, phù hợp dùng trà hoặc nước ấm tại nhà. Kiểm tra nhiệt độ trước khi uống và cầm chắc bằng quai.',sponsored:false},{id:'lamp',name:'Đèn bàn đọc sách',price:249000,category:'Đồ dùng',img:'lamp',shop:'Nhà Thân Quen',desc:'Đèn bàn gọn gàng dành cho góc đọc sách. Có công tắc dễ sử dụng. Ảnh và thông số trong bản demo chỉ mang tính minh họa.',sponsored:false},{id:'chess',name:'Bộ cờ vua cùng bạn',price:189000,category:'Sở thích',img:'chess',shop:'Vui Mỗi Ngày',desc:'Một bộ cờ để cùng bạn bè thư giãn, luyện tập và tạo thêm câu chuyện mỗi ngày. Bàn cờ 30cm; thông tin minh họa.',sponsored:false}];
