const defaultState=()=>({view:'experience',screen:'home',role:'senior',font:0,filter:'Tất cả',search:'',questionId:1,productId:'tea',chatId:'huong',points:120,redeemed:false,questions:structuredClone(initialQuestions),likes:[],helpful:[],friends:[],messages:{huong:[{me:false,text:'Chào bác Minh! Tôi thấy bác cũng thích trồng hoa. Vườn nhà bác đang có hoa gì thế?'},{me:true,text:'Chào cô Hương, nhà tôi đang có mấy chậu hoa giấy nở đẹp lắm!'}],minhanh:[{me:false,text:'Cháu chào bác! Nếu bác cần hướng dẫn thêm cách gọi video, bác cứ nhắn cháu nhé.'}]},newPosts:[],familyOrder:null,joined:false,support:null,helperId:'minhanh',supportIssue:'Gọi video',supportLandmark:'Hồ Hoàn Kiếm, Hà Nội'});
let state=defaultState();
try{const saved=JSON.parse(localStorage.getItem('anvui-demo-v1'));if(saved)state={...state,...saved,view:'experience',screen:'home',search:'',filter:'Tất cả'};}catch{}
{const v=new URLSearchParams(location.search).get('view');if(['business','launch','campaign'].includes(v))state.view=v;}
if(new URLSearchParams(location.search).has('app'))document.body.classList.add('phone-only');
const isIOS=/iPhone|iPad|iPod/.test(navigator.userAgent)||(navigator.platform==='MacIntel'&&navigator.maxTouchPoints>1);
const isStandalone=navigator.standalone===true||!!window.matchMedia?.('(display-mode: standalone)').matches;
if(isStandalone||(document.body.classList.contains('phone-only')&&window.matchMedia?.('(max-width: 500px)').matches)){document.body.classList.add('phone-only','app-native');state.view='experience'}
function installDismissed(){try{return localStorage.getItem('anvui-install-hint')==='hidden'}catch{return false}}
function installBanner(){if(!isIOS||isStandalone||installDismissed())return '';return `<div class="install-banner">${icon('download')}<div><strong>Đặt An Vui ra màn hình chính</strong><p>Mở như một ứng dụng, không cần App Store.</p><div class="install-banner-actions"><button class="primary" data-action="install">Xem cách làm</button><button class="text-link" data-action="install-dismiss">Để sau</button></div></div></div>`}
function pushNav(){try{const cur=history.state;if(cur&&cur.view===state.view&&cur.screen===state.screen)return;history.pushState({view:state.view,screen:state.screen},'')}catch{}}
let toastTimer,installPrompt,recognition;
const $=s=>document.querySelector(s);
function todayLabel(){try{const s=new Date().toLocaleDateString('vi-VN',{weekday:'long',day:'numeric',month:'numeric'});return s.charAt(0).toUpperCase()+s.slice(1)}catch{return 'Hôm nay'}}
function persist(){try{localStorage.setItem('anvui-demo-v1',JSON.stringify(state))}catch{}}
function toast(message){const el=$('#toast');el.textContent=message;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),4200)}
function avatar(initials,color=''){return `<span class="avatar ${color}">${esc(initials)}</span>`}
function verified(){return `<span class="verified" title="Xác thực minh họa">${icon('badge')}</span>`}
function person(name,initials,detail,color=''){return `<div class="person-line">${avatar(initials,color)}<div class="person-info"><div class="person-name">${esc(name)}${verified()}</div><div class="person-detail">${esc(detail)}</div></div></div>`}
function screenTo(screen,fromHistory=false){state.screen=screen;state.search='';state.filter='Tất cả';state.view='experience';persist();if(!fromHistory)pushNav();render();$('#app-scroll')?.scrollTo(0,0)}
function switchRole(role){state.role=role;state.screen=role==='helper'?'questions':'home';state.search='';state.filter='Tất cả';persist();render();toast(role==='helper'?'Đang trải nghiệm vai trò người hỗ trợ':'Đang trải nghiệm vai trò cô bác')}
function render(){document.querySelectorAll('[data-view]').forEach(el=>el.classList.toggle('active',el.dataset.view===state.view));$('#page').innerHTML=state.view==='experience'?experience():state.view==='business'?business():state.view==='campaign'?campaign():launch();if(state.view==='experience')renderScreen();else if(state.view==='business')updateCalculator();}
function experience(){const helper=state.role==='helper';return `<section class="experience"><div class="hero-copy"><div class="eyebrow">CỘNG ĐỒNG CHO TUỔI VÀNG</div><h1>Thêm bạn.<br>Thêm niềm vui<br><em>mỗi ngày.</em></h1><p class="hero-description">Một nơi thân quen để cô bác trò chuyện, học điều mới và luôn có người sẵn lòng giúp đỡ.</p><div class="hero-actions"><button class="primary" data-action="onboarding">Cùng khám phá An Vui ${icon('arrow')}</button></div><div class="hero-trust">${icon('shield')} Dễ sử dụng · Kết nối có xác thực</div><div class="decor-sprout">${icon('leaf')} Niềm vui lớn lên từ những điều nhỏ.</div></div><div class="phone-wrap"><div class="phone" aria-label="Ứng dụng An Vui trên điện thoại"><div class="phone-status"><span>9:41</span><span class="status-icons">${icon('signal')}${icon('wifi')}${icon('battery')}</span></div><div class="app-header"><div class="app-brand"><button class="zen-mark" data-action="about-zentech" aria-label="Zentech — nhóm phát triển An Vui"><img src="assets/zentech-mark.webp" alt="" width="30" height="30"></button><span class="brand-divider" aria-hidden="true"></span>${brandLockup()}</div><div class="app-header-actions"><button class="icon-button" data-action="font" aria-label="Đổi cỡ chữ" title="Đổi cỡ chữ">${icon('textsize')}</button><button class="icon-button" data-action="notifications" aria-label="Thông báo">${icon('bell')}<span class="dot"></span></button><button class="avatar ${helper?'orange':''}" data-screen="profile" aria-label="Tài khoản của bạn">${helper?'MA':'M'}</button></div></div><div id="app-scroll" class="app-scroll ${state.font===1?'large-text':state.font===2?'extra-large':''} ${state.compact?'compact':''}" tabindex="-1">${state.compact?'<div class="demo-strip">Bản thử nghiệm · Dữ liệu mẫu, không giao dịch thật</div>':''}<div class="app-content" id="app-content"></div></div><nav class="bottom-nav" aria-label="Điều hướng ứng dụng">${[['home','home','Trang chủ'],['questions','message','Hỏi đáp'],[helper?'rewards':'market',helper?'award':'store',helper?'Uy tín':'Mua sắm'],['messages','users','Tin nhắn']].map(([s,i,n])=>`<button data-screen="${s}" class="${navActive(s)?'active':''}">${icon(i)}<span>${n}</span></button>`).join('')}</nav><div class="home-indicator"></div></div><div class="phone-caption">Bấm trực tiếp trên điện thoại để trải nghiệm · Có thể cuộn nội dung</div></div><aside class="side-panel"><div class="panel-eyebrow">MỘT ỨNG DỤNG, HAI THẾ HỆ</div><h2>Gần gũi với cô bác.<br>Ý nghĩa với người trẻ.</h2><p class="description">Chọn một vai trò và khám phá câu chuyện của An Vui.</p><div class="role-toggle" aria-label="Chọn vai trò demo"><button data-role="senior" class="${!helper?'active':''}">${icon('user')} Tôi là cô bác</button><button data-role="helper" class="${helper?'active':''}">${icon('heart')} Tôi giúp cô bác</button></div><div class="scenario-list">${(helper?[['questions','01','Giúp một điều nhỏ','Trả lời câu hỏi công nghệ thật dễ hiểu.'],['rewards','02','Tích lũy điểm uy tín','Uy tín đến từ đóng góp hữu ích.'],['requests','03','Chỉ tận tay, hiểu từng bước','Nhận yêu cầu hướng dẫn trực tiếp.']]:[['questions','01','Điều chưa biết, cứ hỏi','Có người trẻ hướng dẫn tận tình.'],['friends','02','Thêm một người bạn mới','Tìm người cùng sở thích để sẻ chia.'],['nearby','03','Có người chỉ tận tay','Chọn người hướng dẫn gần bác.'],['market','04','Mua sắm an tâm','Gian hàng được duyệt, giá cả rõ ràng.']]).map(([s,n,t,d])=>`<button class="scenario ${state.screen===s?'active':''}" data-screen="${s}"><span class="scenario-number">${n}</span><span><strong>${t}</strong><small>${d}</small></span></button>`).join('')}</div><div class="family-card"><span class="mini-icon">${icon('gift')}</span><strong>Món quà nhỏ, ba mẹ thêm vui.</strong><p>Cài giúp ba mẹ trong vài bước. Cùng kết nối, dù ở gần hay xa.</p><button data-action="family">Tôi muốn cài cho ba mẹ ${icon('arrow')}</button></div></aside></section>`}
function navActive(s){if(s==='questions')return ['questions','question','ask'].includes(state.screen);if(s==='market')return ['market','product','checkout','order-success'].includes(state.screen);if(s==='messages')return ['messages','chat','friends'].includes(state.screen);if(s==='home')return ['home','post','nearby','helper-detail','appointment','requests'].includes(state.screen);return s===state.screen}
function renderScreen(){const screens={home,questions,question,ask,market,product,checkout,orderSuccess,friends:friendsScreen,messages,chat,rewards,profile,identity,post:postScreen,nearby,'helper-detail':helperProfile,appointment,requests:supportRequests};const key=state.screen==='order-success'?'orderSuccess':state.screen;$('#app-content').innerHTML=(key==='home'?installBanner():'')+(screens[key]||home)();document.querySelectorAll('.bottom-nav button').forEach(el=>el.classList.toggle('active',navActive(el.dataset.screen)));document.querySelectorAll('.scenario').forEach(el=>el.classList.toggle('active',el.dataset.screen===state.screen));}
function home(){if(state.role==='helper')return `<p class="greeting-date">${todayLabel()}</p><h1 class="greeting">Chào Minh Anh</h1><p class="sub-greeting">Một lời chỉ dẫn, một niềm vui mới.</p><div class="helper-box">${icon('heart')}<div><strong>Cảm ơn bạn đã đồng hành</strong><p>Hãy bắt đầu từ một câu hỏi của cô bác.</p></div></div><button class="primary wide" data-screen="questions">${icon('message')} Giải đáp cho cô bác</button><button class="secondary wide" data-screen="requests">${icon('pin')} Yêu cầu hướng dẫn trực tiếp</button><h2 class="section-label">Việc tốt của bạn hôm nay</h2><div class="community-post"><div class="stat-row"><span>Điểm đóng góp</span><strong>${state.points} điểm</strong></div><p>Viết hướng dẫn ngắn, chia từng bước. Cô bác sẽ cảm ơn sự kiên nhẫn của bạn.</p><button class="secondary wide" data-screen="rewards">${icon('award')} Xem điểm uy tín</button></div><p class="subtle-note">Tài khoản người hỗ trợ được trả lời và nhắn tin. Chức năng đăng bài cộng đồng dành cho cô bác.</p>`;return `<p class="greeting-date">${todayLabel()}</p><h1 class="greeting">Chào bác Minh</h1><p class="sub-greeting">Hôm nay bác có điều gì vui?</p><div class="home-banner"><img src="assets/community.webp" alt="Những người bạn lớn tuổi vui vẻ cùng dùng điện thoại trong vườn"><div class="banner-copy"><span>CÓ BẠN, CÓ NIỀM VUI</span><strong>Tuổi vàng,<br>mình cùng kết nối.</strong><button data-screen="friends">Tìm bạn cùng sở thích ${icon('arrow')}</button></div></div><h2 class="section-label">Bác muốn làm gì hôm nay?</h2><div class="quick-grid"><button class="quick-card" data-screen="ask"><span class="quick-icon">${icon('message')}</span>${icon('arrow','quick-arrow')}<strong>Hỏi điều chưa biết</strong><small>Luôn có người giúp bác</small></button><button class="quick-card peach" data-screen="market"><span class="quick-icon">${icon('store')}</span>${icon('arrow','quick-arrow')}<strong>Mua sắm an tâm</strong><small>Gian hàng đã duyệt</small></button></div><button class="nearby-home-card" data-screen="nearby">${icon('pin')}<span><strong>Cần người chỉ tận tay?</strong><small>Tìm người hướng dẫn gần bác · Có phí</small></span>${icon('chevron')}</button><h2 class="section-label">Chuyện quanh mình <button data-screen="post">${icon('plus')} Chia sẻ</button></h2>${state.newPosts.map((p,i)=>communityPost('Bác Minh','M','Vừa xong · Chia sẻ với bạn bè',p,false,'new-'+i)).join('')}${communityPost('Cô Hương','H','Hà Nội · 20 phút trước','Sáng nay tôi chuẩn bị đất để trồng thêm hoa. Có bác nào cũng thích chăm cây không? 🌿',true,'garden')}<button class="secondary wide" data-screen="friends">${icon('users')} Tìm thêm bạn trò chuyện</button>`}
function communityPost(name,initials,detail,body,picture,id){const liked=state.likes.includes(id);return `<article class="community-post">${person(name,initials,detail,'orange')}<p>${esc(body)}</p>${picture?'<img class="post-picture" src="assets/garden.webp" alt="Cây xanh và những chậu cây trong vườn" loading="lazy">':''}<div class="post-actions"><button class="${liked?'liked':''}" data-like="${id}" aria-pressed="${liked}">${icon('heart')} ${liked?13:12} Thích</button><button data-comment="${id}">${icon('message')} Trò chuyện</button></div></article>`}
function questions(){const helper=state.role==='helper';return `<h1 class="screen-title">${helper?'Cùng giúp cô bác':'Có điều gì, bác cứ hỏi'}</h1><p class="screen-subtitle">${helper?'Chia sẻ điều bạn biết bằng những bước đơn giản.':'Những điều nhỏ, luôn có người sẵn lòng giúp.'}</p>${helper?'':`<button class="primary wide" data-screen="ask">${icon('plus')} Đặt câu hỏi mới</button>`}<label class="search-field">${icon('search')}<input id="question-search" aria-label="Tìm câu hỏi" placeholder="Tìm câu hỏi bác quan tâm" value="${esc(state.search)}"></label><div class="chips">${['Tất cả','Điện thoại','Ứng dụng','An toàn'].map(t=>`<button class="chip ${state.filter===t?'active':''}" data-question-filter="${t}">${t}</button>`).join('')}</div><div id="question-results">${questionList()}</div>`}
function questionList(){const qs=state.questions.filter(q=>(state.filter==='Tất cả'||q.category===state.filter)&&q.title.toLocaleLowerCase('vi').includes(state.search.toLocaleLowerCase('vi')));return qs.length?qs.map(q=>`<button class="question-card" data-question="${q.id}">${person(q.name,q.initials,`${q.age} tuổi · ${q.time}`)}<h3>${esc(q.title)}</h3><div class="question-meta"><span class="tag ${q.category==='An toàn'?'orange':''}">${esc(q.category)}</span><span>${q.answers.length?'Có '+q.answers.length+' câu trả lời':'Đang chờ giúp đỡ'} ${icon('chevron')}</span></div></button>`).join(''):'<div class="empty">Chưa có câu hỏi phù hợp.<br>Bác thử tìm từ khác nhé.</div>'}
function question(){const q=state.questions.find(q=>q.id===state.questionId)||state.questions[0];return `<button class="back-btn" data-screen="questions">${icon('back')} Về mục hỏi đáp</button>${person(q.name,q.initials,`${q.age} tuổi · ${q.time}`)}<h1 class="screen-title question-title">${esc(q.title)}</h1><p class="question-body">${esc(q.body)}</p><div class="safe-note">${icon('shield')} Bác không chia sẻ mật khẩu, mã OTP hoặc ảnh căn cước trong câu hỏi nhé.</div><h2 class="section-label">Câu trả lời (${q.answers.length})</h2>${q.answers.map(a=>`<article class="answer-card">${person(a.name,a.initials,a.reviewed?'Người hỗ trợ · Nội dung mẫu đã duyệt':'Người hỗ trợ · Chờ kiểm duyệt','orange')}<p>${esc(a.body)}</p>${state.role==='senior'?`<button class="answer-helpful ${state.helpful.includes(a.id)?'selected':''}" data-helpful="${a.id}" aria-pressed="${state.helpful.includes(a.id)}">${icon('thumb')} ${state.helpful.includes(a.id)?'Cảm ơn, tôi đã làm được':'Hữu ích, tôi đã làm được'} · ${a.likes+(state.helpful.includes(a.id)?1:0)}</button>`:`<span class="tag">${icon('heart')} ${a.likes+(state.helpful.includes(a.id)?1:0)} lượt hữu ích</span>`}</article>`).join('')||'<p class="subtle-note">Câu hỏi đang chờ người hỗ trợ trả lời.</p>'}${state.role==='helper'?`<form id="answer-form"><label class="field-label" for="answer-body">Câu trả lời của bạn</label><textarea class="form-control" id="answer-body" name="body" required minlength="15" maxlength="2000" placeholder="Hãy chỉ dẫn từng bước, thật dễ hiểu..."></textarea><p class="subtle-note">Câu trả lời mới chờ kiểm duyệt. Điểm chỉ được cộng sau khi câu trả lời được duyệt và cô bác xác nhận hữu ích.</p><button class="primary wide" type="submit">${icon('send')} Gửi câu trả lời</button></form>`:`<button class="secondary wide" data-chat="minhanh">${icon('message')} Nhắn người hỗ trợ</button>`}`}
function ask(){if(state.role!=='senior')return denied();return `<button class="back-btn" data-screen="questions">${icon('back')} Về mục hỏi đáp</button><h1 class="screen-title">Bác muốn hỏi điều gì?</h1><p class="screen-subtitle">Bác cứ kể, các cháu sẽ giúp.</p><form id="question-form"><label class="field-label" for="q-title">Bác cần giúp việc gì?</label><input id="q-title" name="title" class="form-control" required minlength="8" maxlength="150" placeholder="Ví dụ: Bác muốn gọi video cho cháu"><label class="field-label" for="q-category">Việc này liên quan đến</label><select id="q-category" class="form-control" name="category"><option>Điện thoại</option><option>Ứng dụng</option><option>An toàn</option></select><label class="field-label" for="q-body">Bác kể thêm một chút nhé</label><textarea id="q-body" name="body" class="form-control" required minlength="10" maxlength="2000" placeholder="Bác đang gặp khó khăn ở bước nào?"></textarea><button type="button" class="secondary wide" data-action="dictate">${icon('mic')} Nói thay vì gõ</button><div class="safe-note">${icon('shield')} Câu hỏi sẽ được chia sẻ với cộng đồng. Bác đừng ghi số điện thoại, mật khẩu hay mã OTP nhé.</div><button type="submit" class="primary wide">${icon('send')} Gửi câu hỏi</button></form>`}
function denied(){return `<div class="empty">Chức năng này dành cho tài khoản cô bác.</div><button class="primary wide" data-screen="questions">Cùng giải đáp câu hỏi</button>`}
function postScreen(){if(state.role!=='senior')return denied();return `<button class="back-btn" data-screen="home">${icon('back')} Về trang chủ</button><h1 class="screen-title">Chia sẻ niềm vui</h1><p class="screen-subtitle">Một câu chuyện nhỏ cũng làm ngày thêm vui.</p><form id="post-form"><label class="field-label" for="post-body">Bác muốn kể điều gì?</label><textarea class="form-control" id="post-body" name="body" required minlength="5" maxlength="1500" placeholder="Hôm nay tôi..."></textarea><p class="subtle-note">Bài viết hiển thị trong cộng đồng demo. Bác không đưa thông tin riêng tư vào bài nhé.</p><button class="primary wide" type="submit">${icon('plus')} Chia sẻ với mọi người</button></form>`}
function market(){if(state.role==='helper')return rewards();return `<h1 class="screen-title">Mua sắm an tâm</h1><p class="screen-subtitle">Món quà nhỏ cho mình và người thân, từ gian hàng đã duyệt.</p><div class="safe-note positive">${icon('shield')} Gian hàng được duyệt riêng. Sản phẩm và giá trong demo đều là minh họa.</div><div class="chips">${['Tất cả','Thư giãn','Đồ dùng','Sở thích'].map(t=>`<button class="chip ${state.filter===t?'active':''}" data-market-filter="${t}">${t}</button>`).join('')}</div><div class="product-grid">${products.filter(p=>state.filter==='Tất cả'||p.category===state.filter).map(p=>`<button class="product-card" data-product="${p.id}"><img class="product-photo" src="assets/${p.img}.webp" alt="Ảnh minh họa ${esc(p.name)}" loading="lazy"><div class="product-info">${p.sponsored?'<span class="sponsor-tag">Được giới thiệu · Tài trợ</span>':'<span class="tag">Gian hàng đã duyệt*</span>'}<h3>${p.name}</h3><span class="price">${vnd(p.price)}</span><small>${p.shop} · Thông tin mẫu</small></div></button>`).join('')}</div><p class="subtle-note">*Trạng thái xác thực và kiểm duyệt trong bản demo là mô phỏng.</p>`}
function product(){if(state.role!=='senior')return denied();const p=products.find(p=>p.id===state.productId)||products[0];return `<button class="back-btn" data-screen="market">${icon('back')} Về mua sắm</button><article class="product-detail"><img class="product-hero" src="assets/${p.img}.webp" alt="Ảnh minh họa ${p.name}">${p.sponsored?'<span class="sponsor-tag">Vị trí tài trợ · Sản phẩm minh họa</span>':''}<h2>${p.name}</h2><div class="seller-line">${icon('shield')} ${p.shop} · Gian hàng mẫu đã duyệt</div><div class="product-price">${vnd(p.price)}</div><p>${p.desc}</p><div class="safe-note">${icon('info')} Không cần chuyển khoản trước trong demo. Bác có thể nhờ người thân hỗ trợ quyết định mua.</div><div class="product-actions"><button class="primary wide" data-screen="checkout">${icon('bag')} Đặt mua thử</button><button class="secondary wide" data-action="family-order">${icon('gift')} Nhờ con cháu mua giúp</button></div></article>`}
function checkout(){if(state.role!=='senior')return denied();const p=products.find(p=>p.id===state.productId)||products[0];return `<button class="back-btn" data-screen="product">${icon('back')} Xem lại sản phẩm</button><h1 class="screen-title">Kiểm tra đơn của bác</h1><p class="screen-subtitle">Đây là đơn hàng mô phỏng, không thu tiền.</p><div class="community-post"><h2 class="card-title">${p.name}</h2><div class="stat-row"><span>Số lượng</span><strong>1 sản phẩm</strong></div><div class="stat-row"><span>Giá sản phẩm</span><strong>${vnd(p.price)}</strong></div><div class="stat-row"><span>Phí giao mẫu</span><strong>20.000đ</strong></div><div class="stat-row"><span>Tổng cộng</span><strong>${vnd(p.price+20000)}</strong></div></div><div class="notice">Địa chỉ mẫu: Nhà bác Minh, Hà Nội.<br>Thanh toán mẫu: Khi nhận hàng.<br>Không cần nhập thông tin thật.</div><button class="primary wide" data-screen="order-success">${icon('check')} Xác nhận đặt thử</button>`}
function orderSuccess(){if(state.role!=='senior')return denied();return `<div class="success-block"><div class="success-icon">${icon('check')}</div><h1 class="screen-title">Bác đã đặt thử thành công!</h1><p>An Vui đã ghi nhận đơn hàng minh họa. Không có đơn thật được gửi đến cửa hàng và không phát sinh thanh toán.</p><button class="primary wide" data-screen="market">${icon('store')} Tiếp tục mua sắm</button><button class="secondary wide" data-screen="home">Về trang chủ</button></div>`}
function friendsScreen(){if(state.role==='helper')return messages();return `<button class="back-btn" data-screen="home">${icon('back')} Về trang chủ</button><h1 class="screen-title">Bạn mới, niềm vui mới</h1><p class="screen-subtitle">Những cô bác có cùng sở thích với mình.</p>${friends.map(f=>`<article class="friend-card">${person(f.name,f.initials,`${f.age} tuổi · ${f.place}`,f.color)}<p>${f.bio}</p><div class="interest-tags">${f.interests.map(t=>`<span class="tag">${t}</span>`).join('')}</div><button class="secondary" ${state.friends.includes(f.id)?`data-chat="${f.id}"`:`data-friend="${f.id}"`}>${icon(state.friends.includes(f.id)?'message':'user-plus')} ${state.friends.includes(f.id)?'Đã kết bạn · Nhắn tin':'Gửi lời kết bạn'}</button></article>`).join('')}<p class="subtle-note">Trong demo, lời mời được chấp nhận tự động để bác thử nhắn tin. Vị trí chỉ hiển thị cấp thành phố.</p>`}
function messages(){return `<h1 class="screen-title">Tin nhắn</h1><p class="screen-subtitle">Một lời hỏi thăm, thêm chút ấm lòng.</p>${state.role==='senior'?'<button class="secondary wide" data-screen="friends">'+icon('users')+' Tìm bạn cùng sở thích</button>':''}<div class="conversation-list">${Object.keys(state.messages).map(id=>{const f=friends.find(f=>f.id===id)||{name:'Minh Anh',initials:'MA',color:'orange'};const ms=state.messages[id];return `<button class="conversation" data-chat="${id}">${avatar(f.initials,f.color)}<span class="person-info"><strong>${state.role==='helper'&&id==='minhanh'?'Bác Minh':f.name}</strong><p>${esc(ms[ms.length-1]?.text.slice(0,49)||'Cùng bắt đầu câu chuyện nhé!')}</p></span><time>Hôm nay</time></button>`}).join('')}</div><div class="safe-note">${icon('shield')} Bác có thể chặn hoặc báo cáo nếu một cuộc trò chuyện khiến bác không thoải mái.</div>`}
function chat(){const f=friends.find(f=>f.id===state.chatId)||{name:state.role==='helper'?'Bác Minh':'Minh Anh',initials:state.role==='helper'?'M':'MA',color:'orange'};return `<button class="back-btn" data-screen="messages">${icon('back')} Về tin nhắn</button>${person(f.name,f.initials,'Bạn trong cộng đồng An Vui',f.color)}<div class="chat-bubbles">${(state.messages[state.chatId]||[]).map(m=>`<div class="bubble ${m.me?'me':''}">${esc(m.text)}</div>`).join('')}</div><form id="chat-form" class="chat-form"><input class="form-control" name="message" id="chat-input" aria-label="Nội dung tin nhắn" placeholder="Viết lời nhắn..." required maxlength="1500" autocomplete="off"><button class="primary" type="submit" aria-label="Gửi tin nhắn">${icon('send')}</button></form><p class="subtle-note">Tin nhắn chỉ lưu trên thiết bị này. Không có người thật đang trò chuyện.</p><button class="ghost-button danger" data-action="report">${icon('flag')} Báo cáo hoặc chặn liên hệ</button>`}
function rewards(){const available=Math.min(100,state.points/200*100);return `<h1 class="screen-title">Điểm uy tín của bạn</h1><p class="screen-subtitle">Mỗi đóng góp hữu ích đều được ghi nhận.</p><div class="helper-box"><span class="points">${state.points}</span><div><strong>điểm đóng góp</strong><p>Uy tín lớn lên từ sự tận tâm.</p></div></div><div class="community-post"><span class="tag">${icon('gift')} Ưu đãi cho người có gian hàng</span><h2 class="card-title">200 điểm = ưu đãi hiển thị 7 ngày</h2><div class="progress-track"><div class="progress-fill" style="width:${available}%"></div></div><p class="subtle-note">${state.points>=200?'Bạn đã đạt mốc đổi ưu đãi.':`Còn ${200-state.points} điểm nữa đến mốc đầu tiên.`}</p><button class="${state.points>=200?'primary':'secondary'} wide" data-action="redeem" ${state.redeemed?'disabled':''}>${state.redeemed?'Đã đổi ưu đãi mẫu':'Đổi ưu đãi gian hàng'}</button><p class="subtle-note">Ưu đãi chỉ áp dụng sau khi gian hàng và sản phẩm được duyệt riêng. Vị trí tài trợ luôn có nhãn. Điểm không quy đổi thành tiền.</p></div><h2 class="section-label">Điểm được tính như thế nào?</h2><div class="stat-row"><span>Trả lời được duyệt + người hỏi xác nhận</span><strong>+10 điểm</strong></div><div class="stat-row"><span>Lượt hữu ích hợp lệ từ người khác</span><strong>+2 điểm</strong></div><p class="subtle-note">Thiết kế đề xuất: giới hạn điểm từ lượt thích, kiểm tra tương tác bất thường, đối soát 7 ngày. AI hỗ trợ phát hiện rủi ro; người kiểm duyệt quyết định. Demo chỉ cộng một lần cho nút “Hữu ích”.</p><button class="primary wide" data-screen="questions">${icon('message')} Tiếp tục giúp cô bác</button>`}
function profile(){const helper=state.role==='helper';return `<div class="profile-hero">${avatar(helper?'MA':'M',helper?'orange':'')}<div><h2>${helper?'Minh Anh':'Bác Minh'}</h2><p>${helper?'22 tuổi · Người hỗ trợ':'68 tuổi · Thành viên cô bác'}</p></div></div><span class="tag">${icon('shield')} Đã xác thực · Mô phỏng</span><h2 class="section-label">Để An Vui dễ dùng hơn</h2><button class="setting-row" data-action="font"><span>${icon('textsize')} Cỡ chữ</span><small>${['Lớn','Rất lớn','Lớn nhất'][state.font]}</small></button><button class="setting-row" data-action="read"><span>${icon('volume')} Đọc nội dung màn hình</span>${icon('chevron')}</button><button class="setting-row" data-screen="${helper?'requests':'nearby'}"><span>${icon('pin')} ${helper?'Yêu cầu hướng dẫn':'Nhờ người chỉ tận tay'}</span>${icon('chevron')}</button><button class="setting-row" data-screen="identity"><span>${icon('card')} Xác thực tài khoản</span>${icon('chevron')}</button>${helper?`<button class="setting-row" data-screen="rewards"><span>${icon('award')} Điểm uy tín</span><small>${state.points} điểm</small></button>`:''}<button class="setting-row" data-action="family"><span>${icon('gift')} Kết nối với gia đình</span>${icon('chevron')}</button><button class="setting-row" data-action="install"><span>${icon('download')} Thêm An Vui ra màn hình</span>${icon('chevron')}</button><button class="setting-row" data-action="compact"><span>${icon('eye-off')} Ẩn ghi chú demo</span><small>${state.compact?'Đang bật':'Đang tắt'}</small></button><button class="setting-row" data-action="reset-ask"><span>${icon('reset')} Đặt lại bản demo</span>${icon('chevron')}</button><div class="notice">Đổi vai trò demo</div><div class="role-toggle"><button data-role="senior" class="${!helper?'active':''}">Tôi là cô bác</button><button data-role="helper" class="${helper?'active':''}">Tôi giúp cô bác</button></div><p class="subtle-note">Thông tin là mẫu. Không gửi ảnh căn cước thật vào bản demo.</p><div class="made-by"><img src="assets/zentech-mark.webp" alt="" width="28" height="28"><span>An Vui · phát triển bởi <b>Zentech</b><small>Đơn giản là sức mạnh</small></span></div>`}
function identity(){return `<button class="back-btn" data-screen="profile">${icon('back')} Về tài khoản</button><h1 class="screen-title">Cùng kết nối tin cậy</h1><p class="screen-subtitle">Xác thực độ tuổi để có trải nghiệm phù hợp.</p><div class="notice">Bản demo chỉ mô phỏng kết quả xác thực. Không chụp, tải lên hay lưu căn cước thật.</div><button class="identity-choice" data-verify="senior">${icon('user')}<span><strong>Mẫu: cô bác 68 tuổi</strong><small>Tạo bài viết, hỏi đáp, kết bạn và mua sắm.</small></span></button><button class="identity-choice" data-verify="helper">${icon('heart')}<span><strong>Mẫu: người hỗ trợ 22 tuổi</strong><small>Trả lời, nhắn tin và tích điểm. Không đăng bài.</small></span></button><h2 class="section-label">Thiết kế xác thực đề xuất</h2><p class="subtle-note">Đăng nhập bằng số điện thoại, sau đó xác thực danh tính qua nhà cung cấp phù hợp trước khi tham gia cộng đồng. Chỉ nhận kết quả đã xác thực và nhóm tuổi cần thiết; không đưa ảnh giấy tờ lên diễn đàn.</p><p class="subtle-note">Quy ước bản demo: từ 60 tuổi là nhóm cô bác; từ 18 đến 59 tuổi là người hỗ trợ. Trường hợp xác thực sai cần có bước hỗ trợ và kiểm tra lại.</p>`}
function business(){return `<section class="strategy-page"><div class="strategy-topline"><div class="view-heading"><div class="eyebrow">GIÁ TRỊ THẬT, DOANH THU BỀN VỮNG</div><h1>Cộng đồng là nền tảng.<br>Niềm tin tạo ra giá trị.</h1><p>Cô bác dùng miễn phí những việc thiết yếu. Đối tác và gia đình trả tiền cho dịch vụ có giá trị rõ ràng.</p></div><span class="assumption-pill">Các mức phí là giả định cần thử nghiệm</span></div><div class="revenue-grid"><article class="revenue-card">${icon('store')}<h2>Phí trên đơn thành công</h2><p>Gian hàng trả phí khi giao dịch hoàn tất, đã trừ đơn hủy và hoàn trả.</p><div class="amount">8% <small>/ giá trị sản phẩm</small></div><small>Ưu tiên đồ dùng, sở thích và quà tặng. Bắt đầu với đối tác chọn lọc.</small></article><article class="revenue-card">${icon('wallet')}<h2>Gói gian hàng đối tác</h2><p>Công cụ quản lý đơn, nội dung sản phẩm và báo cáo cho cửa hàng đã duyệt.</p><div class="amount">199.000đ <small>/ gian hàng / tháng</small></div><small>Hiển thị tài trợ có nhãn riêng. Điểm đóng góp đổi ưu đãi, không thay thế duyệt hàng.</small></article><article class="revenue-card">${icon('gift')}<h2>Gói Gia đình An Tâm</h2><p>Đề xuất: hướng dẫn công nghệ theo lịch và hỗ trợ mua quà cho ba mẹ.</p><div class="amount">49.000đ <small>/ gia đình / tháng</small></div><small>Hỏi đáp cộng đồng vẫn miễn phí. Không cho con cháu đọc tin nhắn riêng của ba mẹ.</small></article></div>${serviceRevenue()}<div class="flow"><span>Cô bác có người giúp</span>${icon('arrow')}<span>Cộng đồng có uy tín</span>${icon('arrow')}<span>Mua sắm có niềm tin</span>${icon('arrow')}<span>Đối tác trả phí</span></div><div class="calc-area"><div class="calc-inputs"><h2>Thử bài toán doanh thu</h2><p>Kéo để thay đổi giả định mỗi tháng. Đây là kịch bản minh họa, chưa phải dự báo đã được kiểm chứng.</p>${range('orders','Đơn hoàn tất / tháng',150,0,1000,10)}${range('basket','Giá trị sản phẩm / đơn',300000,100000,700000,50000)}${range('commission','Phí giao dịch',8,0,15,1)}${range('shops','Gian hàng trả phí',10,0,100,1)}${range('families','Gia đình trả phí',20,0,300,5)}${range('costs','Chi phí cố định / tháng',8000000,0,30000000,500000)}<p class="subtle-note">Chi phí biến đổi giả định: 5.000đ/đơn. Chi phí cố định là tổng nhóm tự ước tính cho vận hành, xác thực, kiểm duyệt và tiếp thị. Không gồm thuế hay ưu đãi.</p></div><div class="calc-results" aria-live="polite" id="calc-results"></div></div><div class="strategy-columns"><article class="strategy-section"><h2>Giúp đỡ có chất lượng</h2><ol><li><strong>Người hỏi xác nhận “đã làm được”.</strong> Một câu trả lời đủ điều kiện được +10 điểm một lần.</li><li><strong>AI hỗ trợ sàng lọc.</strong> Câu trả lời công nghệ được đối chiếu hướng dẫn; trường hợp không chắc phải chuyển người kiểm duyệt. Lượt thích không chứng minh câu trả lời đúng.</li><li><strong>Chống trao đổi tương tác.</strong> Giới hạn điểm từ lượt thích, kiểm tra tài khoản liên quan và có thời gian đối soát trước khi đổi ưu đãi.</li><li><strong>Uy tín và hàng hóa được xét riêng.</strong> Người trẻ muốn bán hàng cần đăng ký hồ sơ kinh doanh riêng. Điểm không tự tạo quyền ghim bất kỳ sản phẩm nào.</li></ol></article><article class="strategy-section"><h2>Lý do để tin và quay lại</h2><ul><li><strong>Chữ lớn, thao tác rõ:</strong> nhãn tiếng Việt, vùng bấm rộng, phóng chữ, hỏi bằng giọng nói nếu thiết bị hỗ trợ.</li><li><strong>Con cháu giúp khởi đầu:</strong> cài ra màn hình chính, chọn cỡ chữ, thử cuộc gọi và kết nối một người bạn.</li><li><strong>Ba mẹ giữ quyền riêng tư:</strong> chỉ chia sẻ yêu cầu hỗ trợ hoặc đơn hàng khi chủ động đồng ý.</li><li><strong>Chợ chọn lọc từ đầu:</strong> chưa mở bán tự do hay quảng cáo sản phẩm có tuyên bố chữa bệnh. Quy trình khiếu nại cần có người phụ trách.</li></ul></article></div><div class="sources">Cơ sở thiết kế: <a href="https://www.w3.org/WAI/older-users/developing/" target="_blank" rel="noopener">W3C — Thiết kế web cho người lớn tuổi ↗</a><a href="https://vietnam.unfpa.org/en/topics/ageing-0" target="_blank" rel="noopener">UNFPA Việt Nam — Già hóa dân số ↗</a><br>Các khoản phí, dữ liệu tài khoản, điểm và kết quả kinh doanh trên trang này đều là giả định của bản demo.</div></section>`}
function range(id,label,value,min,max,step){return `<div class="range-field"><label class="calc-label" for="calc-${id}"><span>${label}</span><strong id="label-${id}"></strong></label><input type="range" id="calc-${id}" name="${id}" min="${min}" max="${max}" step="${step}" value="${value}"></div>`}
function calculate({orders,basket,commission,shops,families,costs}){const gross=orders*basket,transaction=gross*commission/100,store=shops*199000,family=families*49000,revenue=transaction+store+family,variable=orders*5000;return{gross,transaction,store,family,revenue,variable,totalCosts:costs+variable,profit:revenue-costs-variable}}
function updateCalculator(){const values={};for(const id of ['orders','basket','commission','shops','families','costs']){values[id]=Number($('#calc-'+id)?.value||0);const el=$('#label-'+id);if(el)el.textContent=['basket','costs'].includes(id)?vnd(values[id]):id==='commission'?values[id]+'%':values[id].toLocaleString('vi-VN')}const c=calculate(values);$('#calc-results').innerHTML=`<div class="eyebrow">DOANH THU ƯỚC TÍNH / THÁNG</div><div class="total">${vnd(c.revenue)}</div><div class="total-label">Tổng doanh thu từ ba nguồn</div><div class="stat-row"><span>Phí giao dịch</span><strong>${vnd(c.transaction)}</strong></div><div class="stat-row"><span>Gói gian hàng</span><strong>${vnd(c.store)}</strong></div><div class="stat-row"><span>Gói gia đình</span><strong>${vnd(c.family)}</strong></div><div class="stat-row"><span>Tổng chi phí giả định</span><strong>${vnd(c.totalCosts)}</strong></div><div class="stat-row result-highlight"><span>${c.profit>=0?'Còn lại trước thuế':'Thiếu để hòa vốn'}</span><strong>${vnd(Math.abs(c.profit))}</strong></div><p class="result-note">Tổng giá trị sản phẩm bán qua chợ (GMV): ${vnd(c.gross)}. GMV không phải doanh thu của An Vui. ${c.profit<0?'Kịch bản hiện tại chưa hòa vốn; cần kiểm chứng nhu cầu trả phí và tối ưu chi phí.':'Kết quả dương phụ thuộc hoàn toàn vào giả định trên; cần thử nghiệm thực tế.'}</p>`}
function launch(){return `<section class="strategy-page"><div class="strategy-topline"><div class="view-heading"><div class="eyebrow">BẮT ĐẦU NHỎ, HỌC TỪ NGƯỜI DÙNG</div><h1>Con cháu giúp cài.<br>Niềm vui giữ ba mẹ ở lại.</h1><p>Không chỉ đo lượt tải. Hãy đo xem cô bác có tự làm được việc mình cần và có muốn quay lại không.</p></div><button class="secondary print-button" data-action="print">${icon('printer')} In kế hoạch</button></div><div class="quote">“Cài cho ba mẹ một nơi có bạn, có người chỉ cách dùng điện thoại và có thêm niềm vui mỗi ngày.”</div><div class="launch-grid"><article class="launch-card"><span class="week">TUẦN 1 · CÙNG HIỂU</span><h2>Gặp đúng người,<br>hỏi đúng khó khăn.</h2><p>Chọn một câu lạc bộ người cao tuổi ở cùng địa bàn để bắt đầu.</p><ul><li>Phỏng vấn 10 cô bác 60–75 tuổi đã có điện thoại thông minh và 5 người con.</li><li>Quan sát thao tác, không chỉ hỏi “bác có thích không”.</li><li>Tuyển 10 người trẻ hỗ trợ trong các khung giờ rõ ràng.</li></ul></article><article class="launch-card"><span class="week">TUẦN 2–3 · CÙNG THỬ</span><h2>Cài một lần,<br>làm được việc ngay.</h2><p>Thử với 30 cô bác, người thân của họ và 3–5 gian hàng chọn lọc.</p><ul><li>Tiếp cận qua câu lạc bộ, tổ dân phố và hoạt động tình nguyện.</li><li>Gửi con cháu video cài giúp dài 30 giây; cho dùng thử trên web trước.</li><li>Buổi đầu hoàn thành 1 câu hỏi và 1 kết nối bạn bè.</li></ul></article><article class="launch-card"><span class="week">TUẦN 4 · CÙNG ĐO</span><h2>Có quay lại?<br>Có sẵn lòng trả phí?</h2><p>Phỏng vấn lại người dùng và đối tác sau khi đã có trải nghiệm.</p><ul><li>Kiểm tra quay lại sau 7 ngày và tỷ lệ câu hỏi giải quyết được.</li><li>Mời đối tác thử một mức phí cụ thể sau các đơn đầu tiên.</li><li>Thử gói hỗ trợ gia đình có phạm vi rõ; ghi nhận cả lý do từ chối.</li></ul></article></div><div class="strategy-columns"><article class="strategy-section"><h2>Hai người dùng, hai lý do bắt đầu</h2><p><strong>Với cô bác:</strong> “Có người kiên nhẫn chỉ tôi cách dùng điện thoại, có bạn cùng sở thích.” Lợi ích phải xuất hiện ngay trong buổi đầu.</p><p><strong>Với con cháu:</strong> “Ba mẹ có nơi hỏi khi mình bận và bớt ngại công nghệ.” Đưa ra bộ cài giúp đơn giản, tôn trọng sự đồng ý của ba mẹ.</p><p><strong>Khuyến khích giới thiệu:</strong> tặng buổi hướng dẫn công nghệ cho gia đình khi một cô bác mới hoàn thành trải nghiệm đầu tiên; không thưởng theo lượt cài đơn thuần.</p></article><article class="strategy-section"><h2>Buổi cài giúp khoảng 5 phút</h2><ol><li><strong>Mở link, dùng thử trước.</strong> Chưa yêu cầu gửi giấy tờ để xem nội dung giới thiệu.</li><li><strong>Thêm ra màn hình chính.</strong> Có biểu tượng An Vui để mở như ứng dụng web.</li><li><strong>Chọn chữ và sở thích.</strong> Để ba mẹ tự thử nút hỏi, gửi tin và quay về trang nhà.</li><li><strong>Xác thực trước khi tương tác thật.</strong> Triển khai sau qua nhà cung cấp; demo chỉ mô phỏng.</li></ol></article></div><article class="strategy-section"><h2>Điều cần chứng minh sau thử nghiệm</h2><p>Các ngưỡng dưới đây là mục tiêu đặt trước để đánh giá, chưa phải số liệu thực tế.</p><table class="metric-table"><thead><tr><th>Giả thuyết</th><th>Cách kiểm tra</th><th>Mục tiêu thử</th></tr></thead><tbody><tr><td>Cô bác tự dùng được</td><td>Tự đăng câu hỏi và mở tin nhắn sau hướng dẫn</td><td>Ít nhất 8/10 người</td></tr><tr><td>Có ích nên quay lại</td><td>Cô bác có hoạt động trong ngày thứ 7</td><td>Ít nhất 40%</td></tr><tr><td>Hỗ trợ giải quyết được việc</td><td>Người hỏi xác nhận đã làm được</td><td>Ít nhất 60% câu hỏi</td></tr><tr><td>Đối tác sẵn lòng trả tiền</td><td>Chấp nhận mức phí cụ thể sau trải nghiệm</td><td>Ít nhất 3/5 đối tác thử</td></tr><tr><td>Con cháu có nhu cầu trả phí</td><td>Đăng ký trả phí cho gói hỗ trợ có phạm vi rõ</td><td>Thử với 10 gia đình</td></tr></tbody></table></article><div class="pitch-script"><h2>Kịch bản thuyết trình 3 phút</h2><p><strong>0:00–0:30 · Vấn đề:</strong> bác Minh muốn gọi cho cháu nhưng ngại hỏi đi hỏi lại. Con bận, bác cần người hướng dẫn dễ hiểu.<br><strong>0:30–1:30 · Demo:</strong> đặt câu hỏi → đổi vai người trẻ → gửi câu trả lời → cô bác xác nhận → tìm bạn và nhắn tin.<br><strong>1:30–2:15 · Doanh thu:</strong> mở Mua sắm, thử nhờ con mua giúp; chuyển bảng doanh thu, thay đổi giả định và chỉ rõ chi phí.<br><strong>2:15–3:00 · Kiểm chứng:</strong> trình bày kế hoạch thử với 30 cô bác, tiêu chí tự dùng được và ý định trả phí thực tế.</p><div class="pitch-actions"><button class="primary" data-action="start-pitch">Bắt đầu trình diễn ${icon('arrow')}</button><button class="secondary" data-view="business">Xem bài toán doanh thu</button></div></div><section class="team-section"><img src="assets/zentech-logo.webp" alt="Logo nhóm Zentech" width="360" height="369"><div><div class="eyebrow team-eyebrow">NHÓM THỰC HIỆN</div><h2>Zentech<br>Đơn giản là sức mạnh.</h2><p><strong>Zen</strong> là tối giản, <strong>Tech</strong> là công nghệ. Zentech hướng đến những sản phẩm công nghệ đơn giản nhưng hiệu quả.</p><p>An Vui là cách nhóm đưa tinh thần ấy đến với cô bác: chữ lớn, ít nút, mỗi màn hình một việc chính và luôn có người chỉ tận tay.</p></div></section></section>`}
function openModal(title,content){$('#modal-content').innerHTML=`<div class="modal-top"><h2 id="modal-title">${title}</h2><button class="icon-button" data-action="close-modal" aria-label="Đóng">${icon('close')}</button></div>${content}`;if(!$('#modal').open)$('#modal').showModal()}
function family(step=0){if(step===1){openModal('Ba mẹ dùng thử ngay',`<div class="family-progress"><span>1. Mở An Vui</span>${icon('arrow')}<span>2. Chọn cỡ chữ</span>${icon('arrow')}<span>3. Thử hỏi đáp</span></div><p class="modal-text">Mở cùng ba mẹ trên điện thoại. Chọn chữ vừa mắt rồi thử hỏi một điều quen thuộc như “Gọi video cho cháu thế nào?”.</p><label class="modal-label">Cỡ chữ của ba mẹ</label><select class="form-control" id="family-font"><option value="0" ${state.font===0?'selected':''}>Lớn — 18px</option><option value="1" ${state.font===1?'selected':''}>Rất lớn — 22px</option><option value="2" ${state.font===2?'selected':''}>Lớn nhất — 26px</option></select><div class="modal-actions"><button class="secondary" data-action="install">${icon('download')} Cách cài ra màn hình</button><button class="primary" data-action="family-finish">Cùng ba mẹ thử ${icon('arrow')}</button></div><p class="subtle-note">Giai đoạn đầu có thể dùng web. Không cần tải từ kho ứng dụng để thử demo.</p>`);return}openModal('Cùng ba mẹ thêm niềm vui',`<p class="modal-text">Ba mẹ có thêm bạn và tự tin hơn với điện thoại. Bạn giúp khởi đầu, ba mẹ chủ động trải nghiệm.</p><div class="modal-feature">${icon('phone')}<div><strong>Cài giúp trong vài bước</strong><p>Thêm biểu tượng ra màn hình, chọn cỡ chữ và thử một câu hỏi cùng ba mẹ.</p></div></div><div class="modal-feature">${icon('shield')}<div><strong>Ba mẹ giữ quyền riêng tư</strong><p>Gia đình chỉ nhận yêu cầu hỗ trợ khi ba mẹ chủ động chia sẻ. Không xem lén tin nhắn.</p></div></div><div class="modal-feature">${icon('gift')}<div><strong>Gói An Tâm — đề xuất 49.000đ/tháng</strong><p>Đang kiểm chứng nhu cầu cho hướng dẫn công nghệ theo lịch và hỗ trợ mua quà. Không thu phí trong demo.</p></div></div><div class="modal-actions"><button class="primary" data-action="family-next">Cài giúp ba mẹ ${icon('arrow')}</button></div>`)}
let onboardingIndex=0;
function onboarding(){const steps=[['message','Điều chưa biết, bác cứ hỏi','Viết câu hỏi hoặc nói bằng giọng nói nếu thiết bị hỗ trợ. Những người trẻ sẽ hướng dẫn bác từng bước.'],['users','Có thêm bạn, ngày thêm vui','Tìm cô bác cùng sở thích, gửi lời kết bạn và bắt đầu bằng một lời hỏi thăm.'],['store','Mua sắm, có người đồng hành','Xem giá rõ ràng, kiểm tra đơn và có thể nhờ con cháu mua giúp.']];const [i,t,d]=steps[onboardingIndex];openModal('Chào mừng bác đến An Vui',`<div class="onboarding-step"><div class="large-icon">${icon(i)}</div><h3>${t}</h3><p>${d}</p><div class="step-dots">${steps.map((_,j)=>`<span class="${j===onboardingIndex?'active':''}"></span>`).join('')}</div></div><div class="modal-actions">${onboardingIndex?'<button class="secondary" data-action="onboarding-back">Quay lại</button>':''}<button class="primary" data-action="onboarding-next">${onboardingIndex===2?'Bác thử ngay nhé':'Tiếp tục'} ${icon('arrow')}</button></div>`)}
function install(){if(installPrompt){installPrompt.prompt();installPrompt.userChoice.then(()=>installPrompt=null);return}openModal('Thêm An Vui ra màn hình',`<p class="modal-text">Mở đường link bản demo bằng trình duyệt trên điện thoại.</p><div class="modal-feature">${icon('phone')}<div><strong>iPhone / iPad</strong><ol class="install-steps"><li>Mở link bằng <b>Safari</b>.</li><li>Bấm nút <b>Chia sẻ</b> (ô vuông có mũi tên lên) ở thanh dưới.</li><li>Kéo xuống, chọn <b>Thêm vào MH chính</b>.</li><li>Bấm <b>Thêm</b>. Biểu tượng An Vui sẽ nằm trên màn hình.</li></ol></div></div><div class="modal-feature">${icon('phone')}<div><strong>Android</strong><p>Trong Chrome, mở menu ⋮ → Thêm vào màn hình chính hoặc Cài đặt ứng dụng, nếu tùy chọn có sẵn.</p></div></div><p class="subtle-note">Đây là ứng dụng web thử nghiệm, chưa có bản trên App Store hay Google Play. Link riêng tư có thể yêu cầu đăng nhập tài khoản chủ sở hữu.</p><div class="modal-actions"><button class="primary" data-action="close-modal">Tôi đã hiểu</button></div>`)}
function dictate(){const SpeechRecognition=window.SpeechRecognition||window.webkitSpeechRecognition;if(!SpeechRecognition){toast('Thiết bị chưa hỗ trợ nhập giọng nói ở đây. Bác có thể bấm biểu tượng mic trên bàn phím điện thoại.');return}try{recognition=new SpeechRecognition();recognition.lang='vi-VN';recognition.interimResults=false;recognition.onresult=e=>{const el=$('#q-body');if(el)el.value+=(el.value?' ':'')+e.results[0][0].transcript;toast('Đã điền lời bác nói vào phần kể thêm. Bác kiểm tra rồi gửi nhé.');};recognition.onerror=()=>toast('Chưa nghe được giọng nói. Bác kiểm tra quyền micro hoặc dùng bàn phím nhé.');recognition.start();toast('Đang nghe… Bác nói nội dung cần hỏi nhé.')}catch{toast('Bác thử lại hoặc dùng bàn phím nhé.')}}
const actions={
 ...featureActions,
 'about-zentech'(){openModal('Về nhóm Zentech',`<div class="about-zen"><img src="assets/zentech-logo.webp" alt="Logo Zentech" width="360" height="369"><p class="about-zen-slogan">Đơn giản là sức mạnh.</p><p class="modal-text"><strong>Zen</strong> là tối giản, <strong>Tech</strong> là công nghệ. Zentech làm những sản phẩm công nghệ đơn giản nhưng hiệu quả. An Vui là sản phẩm của nhóm dành cho người cao tuổi.</p></div><div class="modal-actions"><button class="primary" data-action="close-modal">Đóng</button></div>`)},
 'go-home'(){state.view='experience';screenTo('home');window.scrollTo({top:0,behavior:'smooth'})},
 'reset-ask'(){openModal('Đặt lại bản demo?',`<p class="modal-text">Mọi câu hỏi, tin nhắn, lịch hẹn và điểm vừa thử sẽ bị xóa, quay về dữ liệu mẫu ban đầu.</p><div class="modal-actions"><button class="secondary" data-action="close-modal">Giữ nguyên</button><button class="primary" data-action="reset">Đặt lại</button></div>`)},
 'install-dismiss'(){try{localStorage.setItem('anvui-install-hint','hidden')}catch{}renderScreen()},
 compact(){const pos=$('#app-scroll')?.scrollTop||0;state.compact=!state.compact;persist();render();$('#app-scroll')?.scrollTo(0,pos);toast(state.compact?'Đã ẩn ghi chú demo':'Đã hiện lại ghi chú demo')},
 reset(){livePosition=null;recognition?.abort();window.speechSynthesis?.cancel();state=defaultState();persist();$('#modal').close();try{history.replaceState({view:state.view,screen:state.screen},'')}catch{}render();toast('Đã đưa demo về trạng thái ban đầu')},
 onboarding(){onboardingIndex=0;onboarding()},'onboarding-next'(){if(onboardingIndex<2){onboardingIndex++;onboarding()}else{$('#modal').close();screenTo('ask')}},'onboarding-back'(){onboardingIndex--;onboarding()},
 'close-modal'(){$('#modal').close()},font(){const pos=$('#app-scroll')?.scrollTop||0;state.font=(state.font+1)%3;persist();render();$('#app-scroll')?.scrollTo(0,pos);toast(['Chữ lớn — 18px','Chữ rất lớn — 22px','Chữ lớn nhất — 26px'][state.font])},
 family(){family()},'family-next'(){family(1)},'family-finish'(){state.font=Number($('#family-font')?.value||0);state.role='senior';$('#modal').close();screenTo('ask');toast('Đã chọn cỡ chữ. Bác thử gửi câu hỏi đầu tiên nhé.')},install,dictate,
 notifications(){openModal('Có niềm vui mới',`<div class="modal-feature">${icon('message')}<div><strong>Minh Anh đã trả lời câu hỏi của bác</strong><p>“Bác mở Zalo, chọn cuộc trò chuyện với cháu…”</p><button class="secondary" data-notification-question="1">Xem hướng dẫn mẫu</button></div></div><div class="modal-feature">${icon('users')}<div><strong>Cô Hương muốn làm quen</strong><p>Cô cũng thích trồng hoa và đọc sách như bác.</p><button class="secondary" data-action="notification-friends">Tìm hiểu bạn mới</button></div></div><p class="subtle-note">Thông báo minh họa, không phải hoạt động trực tiếp.</p>`)},
 'notification-friends'(){$('#modal').close();screenTo('friends')},
 'family-order'(){const p=products.find(p=>p.id===state.productId);state.familyOrder=p.id;persist();openModal('Nhờ con cháu mua giúp',`<div class="modal-feature">${icon('gift')}<div><strong>${p.name}</strong><p>${vnd(p.price)} · ${p.shop}</p></div></div><p class="modal-text">Bác chủ động gửi thông tin sản phẩm để người thân cùng xem. Demo chỉ tạo nội dung lời nhắn, chưa gửi cho ai.</p><div class="notice" id="share-order-text">Con xem giúp ba sản phẩm “${p.name}” trên An Vui nhé. Giá mẫu ${vnd(p.price)}; mình cùng kiểm tra trước khi mua.</div><div class="modal-actions"><button class="secondary" data-action="copy-order">${icon('copy')} Sao chép lời nhắn</button><button class="primary" data-action="family-order-done">Xem kết quả mẫu</button></div>`)},
 async 'copy-order'(){try{await navigator.clipboard.writeText($('#share-order-text').textContent);toast('Đã sao chép. Bác dán vào tin nhắn gửi người thân nhé.')}catch{toast('Bác chọn nội dung lời nhắn và sao chép thủ công nhé.')}},
 'family-order-done'(){openModal('Yêu cầu hỗ trợ mẫu đã sẵn sàng',`<div class="success-block in-modal"><div class="success-icon">${icon('gift')}</div><p>Trong sản phẩm thật, người thân nhận yêu cầu khi bác bấm gửi và đồng ý chia sẻ. Họ có thể xem đơn và thanh toán giúp.</p><p class="subtle-note">Bản demo chưa gửi tin nhắn hay kết nối thanh toán.</p><button class="primary wide" data-action="close-modal">Quay lại với bác</button></div>`)},
 redeem(){if(state.points<200){toast('Bạn cần thêm '+(200-state.points)+' điểm. Gian hàng cũng phải được duyệt riêng.');return}state.points-=200;state.redeemed=true;persist();renderScreen();toast('Đã đổi ưu đãi mẫu. Chờ xét duyệt gian hàng; chưa có sản phẩm thật được ghim.')},
 read(){if(!('speechSynthesis'in window)){toast('Trình duyệt này chưa hỗ trợ đọc nội dung. Bác thử tính năng đọc màn hình của điện thoại nhé.');return}window.speechSynthesis.cancel();const text=$('#app-content').innerText;const utterance=new SpeechSynthesisUtterance(text);utterance.lang='vi-VN';utterance.rate=.85;utterance.onerror=()=>toast('Chưa đọc được trên thiết bị này. Bác kiểm tra giọng đọc tiếng Việt nhé.');window.speechSynthesis.speak(utterance);toast('Đang đọc nội dung. Giọng tiếng Việt phụ thuộc thiết bị.')},
 report(){openModal('Bác muốn xử lý thế nào?',`<p class="modal-text">Nếu có lời nhắn làm bác không thoải mái, bác có thể dừng trò chuyện và báo cho An Vui.</p><div class="modal-actions"><button class="secondary" data-action="report-submit">Báo cáo liên hệ</button><button class="primary" data-action="block-submit">Chặn trong demo</button></div><p class="subtle-note">Báo cáo này được mô phỏng; chưa gửi cho người kiểm duyệt thật.</p>`)},
 'report-submit'(){$('#modal').close();toast('Đã ghi nhận báo cáo mẫu. Chưa có báo cáo thật được gửi.')},'block-submit'(){delete state.messages[state.chatId];state.friends=state.friends.filter(id=>id!==state.chatId);persist();$('#modal').close();screenTo('messages');toast('Đã gỡ cuộc trò chuyện trong bản demo')},
 print(){window.print()},'start-pitch'(){state.role='senior';state.view='experience';screenTo('ask');window.scrollTo({top:0,behavior:'smooth'})}
};
document.addEventListener('click',e=>{const el=e.target.closest('button,a[data-action]');if(!el)return;if(el.dataset.action&&el.tagName==='A')e.preventDefault();if(el.disabled)return;if(el.dataset.view){state.view=el.dataset.view;pushNav();render();window.scrollTo({top:0,behavior:'smooth'});return}if(el.dataset.role){switchRole(el.dataset.role);return}if(el.dataset.screen){screenTo(el.dataset.screen);return}if(el.dataset.action){actions[el.dataset.action]?.();return}if(el.dataset.question){state.questionId=Number(el.dataset.question);screenTo('question');return}if(el.dataset.notificationQuestion){state.questionId=Number(el.dataset.notificationQuestion);$('#modal').close();screenTo('question');return}if(el.dataset.questionFilter){state.filter=el.dataset.questionFilter;renderScreen();return}if(el.dataset.marketFilter){state.filter=el.dataset.marketFilter;renderScreen();return}if(el.dataset.product){state.productId=el.dataset.product;screenTo('product');return}if(el.dataset.like){const id=el.dataset.like;state.likes=state.likes.includes(id)?state.likes.filter(x=>x!==id):[...state.likes,id];persist();const pos=$('#app-scroll').scrollTop;renderScreen();$('#app-scroll').scrollTop=pos;return}if(el.dataset.helpful){if(state.role!=='senior')return;const id=el.dataset.helpful;if(state.helpful.includes(id)){toast('Bác đã xác nhận câu trả lời này hữu ích rồi.');return}state.helpful.push(id);const answer=state.questions.flatMap(q=>q.answers).find(a=>a.id===id);if(answer?.reviewed&&answer.name==='Minh Anh')state.points+=10;persist();const pos=$('#app-scroll').scrollTop;renderScreen();$('#app-scroll').scrollTop=pos;toast(answer?.reviewed?'Cảm ơn bác! Đã ghi nhận xác nhận hữu ích.':'Đã ghi nhận; câu trả lời cần được duyệt trước khi cộng điểm.');return}if(el.dataset.friend){const id=el.dataset.friend;if(!state.friends.includes(id))state.friends.push(id);const f=friends.find(f=>f.id===id);if(!state.messages[id])state.messages[id]=[{me:false,text:`Chào bác Minh, rất vui được làm quen với bác! Mình cùng chia sẻ những điều vui nhé.`}];persist();renderScreen();toast(`${f.name} đã chấp nhận lời mời mẫu. Bác có thể nhắn tin rồi.`);return}if(el.dataset.chat){state.chatId=el.dataset.chat;if(!state.messages[state.chatId])state.messages[state.chatId]=[];screenTo('chat');return}if(el.dataset.verify){switchRole(el.dataset.verify);toast('Đã mô phỏng xác thực thành công. Không có giấy tờ nào được thu thập.');return}if(el.dataset.comment){openModal('Cùng trò chuyện với cô Hương',`<p class="modal-text">“Nhà bác cũng có hoa giấy. Lúc nào cô chia sẻ thêm cách chăm hoa nhé!”</p><p class="subtle-note">Mẫu lời hỏi thăm. Bác có thể kết bạn và nhắn tin riêng.</p><div class="modal-actions"><button class="primary" data-action="notification-friends">${icon('users')} Kết nối với cô Hương</button></div>`);}});
document.addEventListener('input',e=>{if(e.target.id==='question-search'){state.search=e.target.value;$('#question-results').innerHTML=questionList()}if(e.target.id.startsWith('calc-'))updateCalculator()});
document.addEventListener('submit',e=>{const form=e.target;if(!['question-form','answer-form','post-form','chat-form'].includes(form.id))return;e.preventDefault();const fd=new FormData(form);if(form.id==='question-form'){if(state.role!=='senior'){toast('Chức năng đăng câu hỏi dành cho cô bác.');return}const title=String(fd.get('title')).trim(),body=String(fd.get('body')).trim();if(title.length<8||body.length<10){toast('Bác ghi thêm một chút để mọi người hiểu câu hỏi nhé.');return}const id=Date.now();state.questions.unshift({id,name:'Bác Minh',initials:'M',age:68,category:String(fd.get('category')),title,body,time:'Vừa xong',answers:[]});state.questionId=id;persist();screenTo('question');toast('Đã đăng câu hỏi mẫu. Chuyển vai người trẻ để thử trả lời.')}if(form.id==='answer-form'){if(state.role!=='helper')return;const body=String(fd.get('body')).trim();if(body.length<15){toast('Bạn viết rõ hơn một chút để cô bác dễ làm theo nhé.');return}const q=state.questions.find(q=>q.id===state.questionId);q.answers.push({id:'answer-'+Date.now(),name:'Minh Anh',initials:'MA',body,likes:0,reviewed:false});persist();renderScreen();toast('Đã gửi câu trả lời mẫu, đang chờ kiểm duyệt.');openModal('Câu trả lời đang chờ duyệt',`<p class="modal-text">Trong sản phẩm thật, hệ thống sàng lọc rủi ro và người kiểm duyệt xử lý nội dung cần kiểm tra. Bản demo cho phép bấm bước duyệt mẫu để trình diễn luồng điểm.</p><p class="subtle-note">Bấm duyệt mẫu không phải kết quả đánh giá của AI hay người thật.</p><div class="modal-actions"><button class="secondary" data-action="close-modal">Để chờ duyệt</button><button class="primary" id="demo-review-answer">Duyệt mẫu</button></div>`);$('#demo-review-answer').addEventListener('click',()=>{q.answers[q.answers.length-1].reviewed=true;persist();$('#modal').close();renderScreen();toast('Đã duyệt mô phỏng. Chuyển sang cô bác để xác nhận hữu ích.')},{once:true})}if(form.id==='post-form'){if(state.role!=='senior')return;const body=String(fd.get('body')).trim();if(body.length<5)return;state.newPosts.unshift(body);persist();screenTo('home');toast('Đã chia sẻ bài viết trong bản demo')}if(form.id==='chat-form'){const text=String(fd.get('message')).trim();if(!text)return;state.messages[state.chatId].push({me:true,text});persist();renderScreen();$('#chat-input')?.focus();$('#app-scroll').scrollTop=$('#app-scroll').scrollHeight;toast('Đã lưu tin nhắn mẫu trên thiết bị này')}});
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=$('#modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('#modal').close()}});
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e});
if('serviceWorker'in navigator)window.addEventListener('load',()=>navigator.serviceWorker.register('./sw.js').catch(()=>{}));
window.addEventListener('popstate',e=>{const s=e.state;if(!s)return;if($('#modal').open)$('#modal').close();if((s.view||'experience')==='experience')screenTo(s.screen||'home',true);else{state.view=s.view;persist();render();window.scrollTo(0,0)}});
try{history.replaceState({view:state.view,screen:state.screen},'')}catch{}
render();
